export default function AdminSystem() { return <SafeAreaView style={styles.safe}><ScrollView contentContainerStyle={styles.content}><Text style={styles.eyebrow}>SYSTEM</Text><Text style={styles.title}>Logs and settings</Text><Text style={styles.subtitle}>Monitor synchronization, audit activity, and console preferences.</Text><View style={styles.cards}>{logs.map((log) => <View style={styles.card} key={log.label}><MaterialCommunityIcons name={log.icon} size={24} color={log.color} /><Text style={styles.label}>{log.label}</Text><Text style={styles.value}>{log.value}</Text></View>)}</View><View style={styles.panel}><Text style={styles.panelTitle}>System controls</Text><Control icon="sync" title="Sync logs" detail="Review successful and failed synchronization attempts" action="View logs" /><Control icon="shield-check-outline" title="Audit logs" detail="See who changed sensitive application data" action="View audit trail" /><Control icon="tune-variant" title="Settings" detail="Configure notifications, retention, and access policies" action="Open settings" /></View></ScrollView></SafeAreaView>; }
